'use strict';
const fs=require('fs');
const path=require('path');
const endpoint='http://127.0.0.1:9235';
const base='http://127.0.0.1:8091/conscious/frontend/modules/vendor/';
const output=path.resolve(__dirname,'../../../docs/mockups');
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function target(){for(let i=0;i<40;i++){try{const pages=await fetch(endpoint+'/json/list').then(r=>r.json());const page=pages.find(x=>x.type==='page');if(page)return page;}catch(error){}await wait(250);}throw new Error('Vendor browser target not found');}
function cdp(url){const socket=new WebSocket(url);const pending=new Map();let id=0;socket.addEventListener('message',event=>{const message=JSON.parse(event.data);if(!message.id||!pending.has(message.id))return;const job=pending.get(message.id);pending.delete(message.id);message.error?job.reject(new Error(message.error.message)):job.resolve(message.result);});const ready=new Promise((resolve,reject)=>{socket.addEventListener('open',resolve,{once:true});socket.addEventListener('error',reject,{once:true});});return{async send(method,params={}){await ready;const call=++id;return new Promise((resolve,reject)=>{pending.set(call,{resolve,reject});socket.send(JSON.stringify({id:call,method,params}));});},close(){socket.close();}};}
async function evaluate(client,expression){const result=await client.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(result.exceptionDetails)throw new Error(result.exceptionDetails.exception?.description||result.exceptionDetails.text);return result.result.value;}
async function navigate(client,route,width=1440,height=1000){await client.send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});await client.send('Page.navigate',{url:base+route});await wait(1500);}
async function screenshot(client,file){const shot=await client.send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false,fromSurface:true});fs.writeFileSync(path.join(output,file),Buffer.from(shot.data,'base64'));}
async function pageHealth(client){return evaluate(client,`(()=>({overflow:getComputedStyle(document.body).overflowX!=='hidden'&&document.documentElement.scrollWidth>document.documentElement.clientWidth+1,broken:Array.from(document.images).filter(i=>!i.complete||i.naturalWidth===0).length,php:/PHP (Warning|Fatal error)|Parse error|Uncaught Error/i.test(document.body.innerText)}))()`);}
async function assertHealthy(client,label){const health=await pageHealth(client);if(health.overflow||health.broken||health.php)throw new Error(label+' failed health check: '+JSON.stringify(health));}
const fillCurrentStep=`(()=>{const panel=document.querySelector('[data-step-panel]:not([hidden])');if(!panel)return false;panel.querySelectorAll('input,select,textarea').forEach(el=>{if(el.disabled)return;if(el.type==='file'){if(!el.required)return;const transfer=new DataTransfer();const count=el.name==='product_samples'?3:1;for(let i=0;i<count;i++)transfer.items.add(new File(['safe demo file'],el.name+'-'+i+'.png',{type:'image/png'}));el.files=transfer.files;el.dispatchEvent(new Event('change',{bubbles:true}));return;}if(el.type==='checkbox'){if(el.required)el.checked=true;return;}if(el.type==='radio'){if(el.required&&!panel.querySelector('[name="'+el.name+'"]:checked'))el.checked=true;return;}if(el.tagName==='SELECT'){if(el.name==='gst_status')el.value='exempt';else{const option=Array.from(el.options).find(o=>o.value);if(option)el.value=option.value;}el.dispatchEvent(new Event('change',{bubbles:true}));return;}let value='Verified demo information for vendor onboarding and marketplace review.';if(el.type==='email')value='vendor@example.com';else if(el.type==='url')value='https://example.com';else if(el.type==='number')value=el.name==='brand_year'?'2020':'5';else if(el.name==='pincode'||el.name==='dispatch_pin')value='302001';else if(el.name==='support_phone')value='9876543210';else if(el.name==='pan')value='ABCDE1234F';else if(el.name==='ifsc')value='ABCD0123456';else if(el.name==='bank_account'||el.name==='bank_confirm')value='123456789012';else if(el.pattern&&el.pattern.includes('[A-Z]{5}'))value='ABCDE1234F';else if(el.pattern&&el.pattern.includes('[A-Z]{4}0'))value='ABCD0123456';else if(el.maxLength>0)value=value.slice(0,Math.max(el.minLength||2,Math.min(el.maxLength,70)));el.value=value;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));});return true;})()`;
async function completeApplication(client,type){await evaluate(client,`sessionStorage.clear();location.href='${base}onboarding.php?type=${type}'`);await wait(1400);const visibility=await evaluate(client,`(()=>({type:document.querySelector('[data-type-name]').textContent.trim(),artisan:!document.querySelector('[data-role-fields="artisan"]').hidden,brand:!document.querySelector('[data-role-fields="brand"]').hidden}))()`);if(visibility.type!==type||visibility.artisan!==(type==='artisan')||visibility.brand!==(type==='brand'))throw new Error(type+' conditional onboarding fields failed');for(let step=1;step<=4;step++){await evaluate(client,fillCurrentStep);const outcome=await evaluate(client,`(()=>{const panel=document.querySelector('[data-step-panel="${step}"]');const invalid=panel.querySelector(':invalid');if(invalid)return{name:invalid.name,message:invalid.validationMessage};panel.querySelector('[data-step-next]').click();return{ok:true};})()`);if(!outcome.ok)throw new Error(type+' step '+step+' invalid: '+JSON.stringify(outcome));await wait(180);}await evaluate(client,fillCurrentStep);const submitted=await evaluate(client,`(()=>{document.querySelector('[data-final-submit]').click();const saved=JSON.parse(sessionStorage.getItem('ci_vendor_onboarding_v2'));return{pending:!document.querySelector('[data-onboarding-pending]').hidden,status:saved.status,type:saved.type,keys:Object.keys(saved)};})()`);if(!submitted.pending||submitted.status!=='submitted'||submitted.type!==type)throw new Error(type+' submission failed: '+JSON.stringify(submitted));const allowed=['type','status','step','reference','submittedAt'];if(submitted.keys.some(key=>!allowed.includes(key)))throw new Error('Sensitive onboarding data entered browser storage');return submitted;}
async function run(){const page=await target();const client=cdp(page.webSocketDebuggerUrl);await client.send('Page.enable');await client.send('Runtime.enable');
await navigate(client,'auth/login.php');await assertHealthy(client,'login');const demo=await evaluate(client,`(()=>{document.querySelector('[data-demo-login="artisan"]').click();return{email:document.querySelector('[name="email"]').value,password:document.querySelector('[name="password"]').value};})()`);if(demo.email!=='artisan@consciousindi.test'||demo.password!=='Vendor@12345')throw new Error('Login demo autofill failed: '+JSON.stringify(demo));await screenshot(client,'vendor-login-desktop.png');await evaluate(client,`document.querySelector('[data-vendor-login]').requestSubmit()`);await wait(900);if(!(await evaluate(client,`location.pathname.endsWith('/vendor/onboarding.php')`)))throw new Error('Demo login did not redirect to onboarding');
await navigate(client,'auth/register.php',390,844);await assertHealthy(client,'registration mobile');const register=await evaluate(client,`(()=>{const artisan=document.querySelector('[name="vendor_type"][value="artisan"]');artisan.click();return{types:document.querySelectorAll('[name="vendor_type"]').length,label:document.querySelector('[data-name-label]').textContent};})()`);if(register.types!==2||!register.label.includes('Artisan'))throw new Error('Registration vendor type selection failed');await screenshot(client,'vendor-register-mobile.png');await evaluate(client,`(()=>{const f=document.querySelector('[data-vendor-register]');f.elements.owner_name.value='Meera Sharma';f.elements.display_name.value='Meera Craft Studio';f.elements.email.value='meera@example.com';f.elements.phone.value='9876543210';f.elements.password.value='Vendor@12345';f.elements.confirm_password.value='Vendor@12345';f.elements.terms.checked=true;f.requestSubmit();})()`);await wait(950);const registrationRedirect=await evaluate(client,`({path:location.pathname,query:location.search})`);if(!registrationRedirect.path.endsWith('/vendor/onboarding.php')||registrationRedirect.query!=='?type=artisan')throw new Error('Registration did not redirect correctly: '+JSON.stringify(registrationRedirect));
await navigate(client,'onboarding.php?type=artisan');await assertHealthy(client,'artisan onboarding');await screenshot(client,'vendor-artisan-onboarding-desktop.png');await completeApplication(client,'artisan');await screenshot(client,'vendor-pending-review-desktop.png');
await navigate(client,'onboarding.php?type=brand',390,844);await assertHealthy(client,'brand onboarding mobile');await screenshot(client,'vendor-brand-onboarding-mobile.png');await completeApplication(client,'brand');
client.close();console.log('VENDOR_AUTH_ONBOARDING_BROWSER_TEST_OK');}
run().catch(error=>{console.error(error.stack||error.message);process.exit(1);});
